def structured_data(name, title, description):
 base = 'https://a1maquetas.com.py/'
 url = base if name == 'index.html' else base + name
 graph = []
 if name == 'index.html':
  graph.extend([
   {'@type': 'Organization', '@id': base + '#organization', 'name': 'A1 Maquetas', 'alternateName': 'A1 - Maquetas arquitectónicas', 'description': 'Sitio oficial del taller de maquetas arquitectónicas de Hernán Kiss en Asunción, Paraguay.', 'founder': {'@type': 'Person', 'name': 'Hernán Kiss'}, 'url': base, 'logo': base + 'assets/logo-a1.jpg', 'email': 'presupuestos@a1maquetas.com.py', 'sameAs': [IG, MAPS], 'areaServed': 'Paraguay'},
   {'@type': 'WebSite', '@id': base + '#website', 'url': base, 'name': 'A1 Maquetas', 'publisher': {'@id': base + '#organization'}, 'inLanguage': 'es-PY'}])
 kind = 'CollectionPage' if name == 'proyectos.html' or name in {c['id'] + '.html' for c in data} else 'AboutPage' if name == 'nosotros.html' else 'ContactPage' if name == 'cotizacion.html' else 'WebPage'
 page_data = {'@type': kind, '@id': url + '#webpage', 'url': url, 'name': title, 'description': description, 'inLanguage': 'es-PY', 'isPartOf': {'@id': base + '#website'}, 'about': {'@id': base + '#organization'}}
 if name != 'index.html':
  category = next((c for c in data if name == c['id'] + '.html'), None)
  crumbs = [{'@type': 'ListItem', 'position': 1, 'name': 'Inicio', 'item': base}]
  if category:
   crumbs.append({'@type': 'ListItem', 'position': 2, 'name': 'Portfolio', 'item': base + 'proyectos.html'})
  crumbs.append({'@type': 'ListItem', 'position': len(crumbs) + 1, 'name': category['name'] if category else 'Portfolio' if name == 'proyectos.html' else 'Nosotros' if name == 'nosotros.html' else 'Cotización', 'item': url})
  graph.append({'@type': 'BreadcrumbList', '@id': url + '#breadcrumb', 'itemListElement': crumbs})
  page_data['breadcrumb'] = {'@id': url + '#breadcrumb'}
  if category:
   graph.append({'@type': 'ItemList', '@id': url + '#projects', 'name': 'Selección de ' + category['name'].lower() + ' de A1 Maquetas', 'itemListElement': [{'@type': 'ListItem', 'position': i, 'name': project, 'url': url + '#proyecto-' + str(i)} for i, project in enumerate(category['projects'], 1)]})
   page_data['mainEntity'] = {'@id': url + '#projects'}
 graph.append(page_data)
 return '<script type="application/ld+json">' + json.dumps({'@context': 'https://schema.org', '@graph': graph}, ensure_ascii=False) + '</script>'
